/**
 * The buildings of one chunk, as geometry (spec sections 9.2, 10.1, 10.3).
 *
 * `buildings.ts` says where a building stands and what kind it is. This says
 * what it looks like: the massing it fills, the shell that is generated for it,
 * and the hull that outlines it.
 *
 * A tower and a mid-rise block are generated by `SkyscraperGenerator`, which
 * gives the chamfers, setbacks, string courses and varied bays of spec section
 * 10.3 from one seed. Every other kind is a few boxes from `block-mesh.ts`; so
 * is a tower on a lot too narrow to generate a facade on, because the generator
 * needs room for its bays.
 *
 * A building never stands on a road, by construction (spec section 1.1). The lot
 * is already inside its parcel, and a parcel is the land the road footprint
 * leaves; the shell is then fitted inside the lot. Its massing is the lot less a
 * margin, a generated facade is asked for {@link CORNICE} less than that because
 * its cornices and crown overhang whatever footprint it is given, and whatever
 * still reaches past the massing is taken in by the scale of the placement. So
 * the last step is measured rather than estimated, and the sweep checks it.
 *
 * A building's own frame has the middle of its lot at the origin, `x` along the
 * frontage, `z` towards the road and `y` up from the ground it stands on. The
 * matrix of a placement is what puts that frame in the world.
 *
 * Nothing here touches the renderer or TSL, so it runs headless and the tests
 * read it directly.
 */
import { Box3, BufferAttribute, BufferGeometry, Color, Matrix4, Quaternion, Vector3 } from 'three';
import { SkyscraperGenerator, pickBuildingColor } from 'three/examples/jsm/generators/city/SkyscraperGenerator.js';
import { hashInts } from '../core/hash.ts';
import { lotMiddle, type Building, type BuildingKind } from '../world/buildings.ts';
import type { WorldChunk, WorldLayers } from '../world/chunks.ts';
import type { RoadEdge, RoadGraph } from '../world/graph.ts';
import type { District, Point, WorldDescription } from '../world/types.ts';
import { buildBlockGeometry } from './block-mesh.ts';
import type { ChunkDetail } from './streaming.ts';

/** A colour as the renderer wants it: three floats in the working colour space. */
export type Rgb = readonly [number, number, number];

/** Which batch a building's shell belongs to, and so how it is generated. */
export type BuildingBatch = 'facade' | 'block';

/** The box a building's shell fills, in its own frame. */
export interface BuildingMassing {
  /** Metres along the frontage. */
  width: number;
  /** Metres from the front of the lot to the back of it. */
  depth: number;
  /** Metres from the ground to the top of the walls, before any roof. */
  height: number;
  /**
   * Which front corner is cut away to face a junction: 1 the corner at the first
   * point of the lot, -1 the corner at the second, 0 neither. Only a generated
   * facade takes one.
   */
  chamfer: number;
}

/** One building, ready for a batch. */
export interface BuildingPlacement {
  building: Building;
  massing: BuildingMassing;
  batch: BuildingBatch;
  /** The shell, in the building's own frame. */
  shell: BufferGeometry;
  /**
   * The inverted hull that outlines it, in the same frame. Only near detail
   * carries one: an outline is a line a few centimetres wide, and the far ring
   * cannot tell it from the building it rims (spec section 9.1).
   */
  hull?: BufferGeometry;
  /** The building's frame in the world. */
  matrix: Matrix4;
}

/** Metres the shell stands in from the edge of its lot, so two neighbours never meet. */
const KIND_MARGIN: Record<BuildingKind, number> = {
  tower: 0.5,
  'mid-rise': 0.5,
  'shop-row': 0.4,
  house: 0.9,
  warehouse: 0.8,
  roadhouse: 1.2,
};

/**
 * Metres a generated facade reaches out past the footprint it is given: the
 * cornices of its base, its string courses and its crown all overhang. The
 * footprint is shrunk by this much on every side, so the whole shell stands
 * inside the lot.
 */
const CORNICE = 2;

/** Metres of facade the generator needs each way. A lot narrower than this takes a block. */
const MIN_FACADE = 8;

/** Metres each way the massing is never allowed below, however small the lot. */
const MIN_MASSING = 4;

/** How tall each kind stands, before the district and the lot have their say. */
const KIND_HEIGHT: Record<BuildingKind, { low: number; high: number }> = {
  tower: { low: 48, high: 150 },
  'mid-rise': { low: 14, high: 34 },
  'shop-row': { low: 7.5, high: 11.5 },
  house: { low: 4.5, high: 9.5 },
  warehouse: { low: 7, high: 13 },
  roadhouse: { low: 4, high: 6 },
};

/**
 * How many times its own narrow side a building may stand. A tower buys its room
 * upwards, but a tall one needs a lot to stand on: this is what keeps a narrow
 * corner lot from carrying a spire.
 */
const MAX_SLENDERNESS = 7;

/** How much of a building's height comes from the district rather than its own seed. */
const DISTRICT_SHARE = 0.45;

/** The generator's bay and floor, in metres. Both are wider than a real tower's:
 * the camera looks down from 60 m, and every window it cannot see is geometry
 * the frame pays for. */
const BAY_WIDTH = 4.2;
const FLOOR_HEIGHT = 4;

/** Metres of the chamfer cut off a corner that faces a junction, at most. */
const CHAMFER_WIDTH = 3;
/** Metres a lot corner may stand from a junction and still be cut for it. */
const CHAMFER_REACH = 16;
/** Edges leaving a node before it counts as a junction rather than a bend. */
const JUNCTION_DEGREE = 3;

/** Metres the base of a building is sunk, so no daylight shows under a wall on a slope. */
const FOUNDATION = 0.5;

/** Metres the outline hull stands outside the shell it rims (spec section 10.1). */
export const OUTLINE_WIDTH = 0.35;

/**
 * Metres of height one band of an outline hull covers, and the most bands one
 * hull is cut into. A hull follows the shape of the building band by band, so a
 * setback is outlined where it stands rather than buried inside a box; a band
 * this deep costs a few dozen vertices and reads as a straight wall from above.
 */
const HULL_BAND = 1;
const HULL_BANDS = 80;

/**
 * The colours each kind of block is built in. A tower takes the masonry palette
 * of the generator instead, which is what its material is written against.
 */
const BLOCK_PALETTE: Record<BuildingKind, readonly number[]> = {
  tower: [0xb4afa1],
  'mid-rise': [0xb0a99d, 0xa89c8a, 0xbcae97],
  'shop-row': [0xc9b394, 0xd0a07c, 0xb9a88c, 0xcdc0a6],
  house: [0xd8c9a8, 0xc9b190, 0xbfc2ad, 0xd6b7a2, 0xc0ccc6, 0xe0d3b6],
  warehouse: [0x9aa0a2, 0x8e8f8a, 0xa39a8c],
  roadhouse: [0xd2c6ad, 0xc2a98c, 0xcfb9a0],
};

/** What a building's geometry asks about the world around it. */
export interface BuildingLookup {
  /** The carved height at a place: the ground a building stands on. */
  heightAt(x: number, y: number): number;
  /** The district a building's lot stands in, which says how tall it builds. */
  districtOf(building: Building): District;
  /** Which front corner of a lot faces a junction, as {@link BuildingMassing.chamfer}. */
  chamferOf(building: Building): number;
}

/** The lookup a world answers with, built once and shared by every chunk of it. */
export function buildingLookup(world: WorldDescription, layers: WorldLayers): BuildingLookup {
  return {
    heightAt: (x, y) => layers.carve.heightAt(x, y),
    districtOf: (building) => world.districts[building.district] as District,
    chamferOf: (building) => chamferOf(building, layers.graph),
  };
}

/**
 * Build the buildings of one chunk, in the order the chunk lists them. Each
 * placement owns its geometry until the caller has copied it into a batch.
 *
 * Far detail is the massing alone (spec section 9.1): every building is a
 * block, however tall it stands, and none is outlined. A generated facade is
 * the dearest thing a chunk builds and its windows are a metre across, so the
 * far ring pays for neither.
 */
export function buildChunkBuildings(
  chunk: WorldChunk,
  lookup: BuildingLookup,
  detail: ChunkDetail = 'near',
): BuildingPlacement[] {
  const out: BuildingPlacement[] = [];
  for (const building of chunk.buildings) {
    const massing = massingOf(building, lookup.districtOf(building), lookup.chamferOf(building));
    const batch = detail === 'far' ? 'block' : batchOf(building.kind, massing);
    const tint = tintOf(building, batch);
    const shell =
      batch === 'facade' ? facadeGeometry(building, massing, tint) : buildBlockGeometry(building.kind, massing, tint);
    const box = centreOnLot(shell);
    const fit = fitOf(box, massing);
    const placed: BuildingPlacement = { building, massing, batch, shell, matrix: matrixOf(building, lookup, fit) };
    if (detail === 'near') placed.hull = hullOf(massing, shell, box, fit);
    out.push(placed);
  }
  return out;
}

/**
 * Draw calls a chunk spends on its buildings: one batch of generated facades,
 * one of blocks, and one of the hulls that outline both. A chunk with no
 * building of a kind pays nothing for it.
 */
export function buildingDrawCalls(chunk: WorldChunk): number {
  let facades = 0;
  let blocks = 0;
  for (const building of chunk.buildings) {
    if (batchOf(building.kind, plan(building)) === 'facade') facades++;
    else blocks++;
  }
  if (facades + blocks === 0) return 0;
  return (facades > 0 ? 1 : 0) + (blocks > 0 ? 1 : 0) + 1;
}

/** The massing of a building, from its lot, its kind and the district it stands in. */
export function massingOf(building: Building, district: District, chamfer: number): BuildingMassing {
  const flat = plan(building);
  const span = KIND_HEIGHT[building.kind];
  // The district has its say on the kinds that grow tall; a house is a house
  // wherever it stands.
  const crowd = building.kind === 'tower' ? (district.density + district.wealth) / 2 : district.density;
  const pull = building.kind === 'tower' || building.kind === 'mid-rise' ? DISTRICT_SHARE : 0;
  const t = unit(building.seed, 1) * (1 - pull) + crowd * pull;
  // A tall building needs a lot to stand on: its own narrow side is what caps it.
  const ceiling = Math.min(span.high, Math.max(span.low, Math.min(flat.width, flat.depth) * MAX_SLENDERNESS));
  return { width: flat.width, depth: flat.depth, height: span.low + (ceiling - span.low) * t, chamfer };
}

/** The ground a building's shell covers, before its height is known. */
function plan(building: Building): { width: number; depth: number } {
  const margin = KIND_MARGIN[building.kind];
  return {
    width: Math.max(MIN_MASSING, building.width - 2 * margin),
    depth: Math.max(MIN_MASSING, building.depth - 2 * margin),
  };
}

/**
 * Which batch a building belongs to. A tower and a mid-rise take a generated
 * facade, but only where the lot leaves the generator room for its bays once the
 * cornices have been allowed for; a narrower one is built as a block.
 */
function batchOf(kind: BuildingKind, massing: { width: number; depth: number }): BuildingBatch {
  if (kind !== 'tower' && kind !== 'mid-rise') return 'block';
  return facadeFootprint(massing).width >= MIN_FACADE && facadeFootprint(massing).depth >= MIN_FACADE
    ? 'facade'
    : 'block';
}

/** The footprint a generated facade is given: the massing less the reach of its cornices. */
function facadeFootprint(massing: { width: number; depth: number }): { width: number; depth: number } {
  return { width: massing.width - 2 * CORNICE, depth: massing.depth - 2 * CORNICE };
}

/** The colour a building is dressed in, from its own seed. */
function tintOf(building: Building, batch: BuildingBatch): Rgb {
  const hex =
    batch === 'facade'
      ? pickBuildingColor(building.seed)
      : (BLOCK_PALETTE[building.kind][hashInts(building.seed, 2) % BLOCK_PALETTE[building.kind].length] as number);
  const colour = new Color(hex);
  return [colour.r, colour.g, colour.b];
}

/**
 * A generated facade, tagged with the building's own colour so one material
 * dresses every tower in the batch.
 */
function facadeGeometry(building: Building, massing: BuildingMassing, tint: Rgb): BufferGeometry {
  const footprint = facadeFootprint(massing);
  const mesh = new SkyscraperGenerator({
    seed: building.seed,
    totalHeight: massing.height,
    floorHeight: FLOOR_HEIGHT,
    bayWidth: BAY_WIDTH,
    footprint,
    // The cut corner faces the junction, and there is only ever one to face.
    chamferWidth: massing.chamfer === 0 ? 0 : Math.min(CHAMFER_WIDTH, footprint.width * 0.25),
    chamferCornerX: massing.chamfer === 0 ? 0 : massing.chamfer,
    chamferCornerZ: 1,
  }).build();
  const geometry = mesh.geometry;
  const count = geometry.getAttribute('position').count;
  const tints = new Float32Array(count * 3);
  for (let v = 0; v < count; v++) {
    tints[v * 3] = tint[0];
    tints[v * 3 + 1] = tint[1];
    tints[v * 3 + 2] = tint[2];
  }
  geometry.setAttribute('tint', new BufferAttribute(tints, 3));
  return geometry;
}

/**
 * Stand a shell in the middle of its lot. A generated facade is not centred on
 * the footprint it was given — a chamfer takes one corner off and a cornice
 * overhangs the rest — so the box it really fills is what is centred, and the
 * whole of it then has the same room around it.
 */
function centreOnLot(shell: BufferGeometry): Box3 {
  shell.computeBoundingBox();
  const box = shell.boundingBox ?? new Box3();
  const dx = -(box.max.x + box.min.x) / 2;
  const dz = -(box.max.z + box.min.z) / 2;
  // The move is written straight into the positions, and the box is moved with
  // them: a shell of a hundred thousand vertices is not walked three times to
  // save a dozen lines.
  const position = shell.getAttribute('position') as BufferAttribute;
  const array = position.array as Float32Array;
  for (let i = 0; i < array.length; i += 3) {
    array[i] = (array[i] as number) + dx;
    array[i + 2] = (array[i + 2] as number) + dz;
  }
  position.needsUpdate = true;
  box.min.x += dx;
  box.max.x += dx;
  box.min.z += dz;
  box.max.z += dz;
  return box;
}

/**
 * How much a shell has to be taken in to stand inside its massing, and so
 * inside its lot and off the road. A generated facade reaches out past the
 * footprint it was given by however much its cornices and its crown overhang,
 * and by more of it on a narrow tower than on a wide one, so the shell is
 * measured rather than trusted. Nothing is ever made larger: a shell that fits
 * is left alone.
 */
function fitOf(box: Box3, massing: BuildingMassing): number {
  const width = box.max.x - box.min.x;
  const depth = box.max.z - box.min.z;
  return Math.min(1, width > 0 ? massing.width / width : 1, depth > 0 ? massing.depth / depth : 1);
}

/**
 * The inverted hull that outlines a building (spec section 10.1). It is the
 * building's massing, not its facade: a shell around every window reveal would
 * cost as much again as the building and draw an outline round detail the
 * top-down camera cannot see.
 *
 * The hull is built around the box the shell really fills, because a crown
 * stands over the height that was asked for and a cornice outside the footprint
 * that was given. It is drawn with the shell's own matrix, so it is widened by
 * the amount the shell is taken in by and comes out {@link OUTLINE_WIDTH} wide
 * on every building whatever its fit.
 */
function hullOf(massing: BuildingMassing, shell: BufferGeometry, box: Box3, fit: number): BufferGeometry {
  const reach = OUTLINE_WIDTH / fit;
  // The shell is centred on the lot, so the box around it is centred on the
  // origin and the ring of the footprint can be laid out there as well.
  const around = { ...massing, width: box.max.x - box.min.x, depth: box.max.z - box.min.z };
  const faces = facesOf(footprintRing(around));
  const bands = profileOf(shell, box, faces, reach);
  const positions: number[] = [];
  const normals: number[] = [];

  for (let b = 0; b < bands.length; b++) {
    const band = bands[b] as Band;
    wall(positions, normals, band.ring, faces, band.y0, band.y1);
    const next = bands[b + 1];
    if (next === undefined) continue;
    // The step between one band and the next, which is what an outline follows
    // round a setback. It looks up where the building draws in and down where it
    // reaches back out.
    for (let i = 0; i < faces.length; i++) {
      if (band.reach[i] === next.reach[i]) continue;
      const from = band.ring;
      const to = next.ring;
      const up = (band.reach[i] as number) > (next.reach[i] as number);
      const j = (i + 1) % faces.length;
      flat(positions, normals, from[i] as Point, from[j] as Point, to[j] as Point, band.y1, up);
      flat(positions, normals, from[i] as Point, to[j] as Point, to[i] as Point, band.y1, up);
    }
  }

  // The caps: a fan from the first corner, so the hull is closed and its rim
  // shows around the roof as well as around the walls.
  const floor = bands[0] as Band;
  const roof = bands[bands.length - 1] as Band;
  for (let i = 1; i + 1 < faces.length; i++) {
    const up = roof.ring;
    const down = floor.ring;
    flat(positions, normals, up[0] as Point, up[i] as Point, up[i + 1] as Point, roof.y1, true);
    flat(positions, normals, down[0] as Point, down[i] as Point, down[i + 1] as Point, floor.y0, false);
  }

  const geometry = new BufferGeometry();
  geometry.setAttribute('position', new BufferAttribute(new Float32Array(positions), 3));
  geometry.setAttribute('normal', new BufferAttribute(new Float32Array(normals), 3));
  return geometry;
}

/** One slice of a hull: the ground it covers, and between which heights. */
interface Band {
  y0: number;
  y1: number;
  /** How far out each face of the footprint stands, in the order `facesOf` gives. */
  reach: number[];
  /** Those faces as a ring of corners. */
  ring: Point[];
}

/**
 * The profile of a shell, band of height by band of height: how far out each
 * face of its footprint reaches over that height, plus the width of the outline.
 *
 * A face is measured from the triangles of the shell rather than from its
 * vertices, and a triangle reaches into every band its own height spans: a wall
 * of one quad from the ground to the roof has no vertex in between, and a band
 * that only asked its vertices would come out empty.
 *
 * Bands that reach the same distance are run together, so a building with
 * straight sides costs one band however tall it is.
 */
function profileOf(shell: BufferGeometry, box: Box3, faces: readonly Point[], reach: number): Band[] {
  const height = Math.max(box.max.y - box.min.y, HULL_BAND);
  const count = Math.max(1, Math.min(HULL_BANDS, Math.ceil(height / HULL_BAND)));
  const step = height / count;
  const out = new Float64Array(count * faces.length).fill(-Infinity);
  const array = (shell.getAttribute('position') as BufferAttribute).array as Float32Array;
  // The shells are not indexed, so three vertices in a row are one triangle.
  for (let t = 0; t + 8 < array.length; t += 9) {
    let low = Infinity;
    let high = -Infinity;
    for (let v = 0; v < 3; v++) {
      const y = array[t + v * 3 + 1] as number;
      low = Math.min(low, y);
      high = Math.max(high, y);
    }
    const from = Math.max(0, Math.min(count - 1, Math.floor((low - box.min.y) / step)));
    const to = Math.max(from, Math.min(count - 1, Math.floor((high - box.min.y) / step)));
    for (let k = 0; k < faces.length; k++) {
      const n = faces[k] as Point;
      let d = -Infinity;
      for (let v = 0; v < 3; v++) {
        d = Math.max(d, (array[t + v * 3] as number) * n.x + (array[t + v * 3 + 2] as number) * n.y);
      }
      for (let b = from; b <= to; b++) if (d > (out[b * faces.length + k] as number)) out[b * faces.length + k] = d;
    }
  }

  const bands: Band[] = [];
  for (let b = 0; b < count; b++) {
    const spread: number[] = [];
    for (let k = 0; k < faces.length; k++) {
      const measured = out[b * faces.length + k] as number;
      // A band no triangle reached takes the one below it, and the lowest band
      // falls back on the box: a hull is never narrower than nothing.
      const fallback = bands[bands.length - 1]?.reach[k] ?? 0;
      spread.push((measured === -Infinity ? fallback : measured) + reach);
    }
    // The hull starts below the ground, so the first band reaches down to the
    // footing, and the last one stands over the roof by the width of the outline.
    const y0 = b === 0 ? -FOUNDATION : box.min.y + b * step;
    const y1 = b === count - 1 ? box.max.y + reach : box.min.y + (b + 1) * step;
    const last = bands[bands.length - 1];
    if (last !== undefined && sameReach(last.reach, spread)) last.y1 = y1;
    else bands.push({ y0, y1, reach: spread, ring: ringOf(faces, spread) });
  }
  return bands;
}

function sameReach(a: readonly number[], b: readonly number[]): boolean {
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

/** The outward unit normal of every edge of a footprint ring, in edge order. */
function facesOf(ring: readonly Point[]): Point[] {
  const out: Point[] = [];
  for (let i = 0; i < ring.length; i++) {
    const a = ring[i] as Point;
    const b = ring[(i + 1) % ring.length] as Point;
    const nx = b.y - a.y;
    const ny = -(b.x - a.x);
    const span = Math.hypot(nx, ny) || 1;
    out.push({ x: nx / span, y: ny / span });
  }
  return out;
}

/**
 * The ring bounded by a set of faces, each pushed out to its own distance. A
 * corner is where two neighbouring faces cross, so pushing one face out moves
 * the two corners of it and nothing else.
 */
function ringOf(faces: readonly Point[], reach: readonly number[]): Point[] {
  const out: Point[] = [];
  for (let i = 0; i < faces.length; i++) {
    const before = faces[(i + faces.length - 1) % faces.length] as Point;
    const here = faces[i] as Point;
    const d0 = reach[(i + faces.length - 1) % faces.length] as number;
    const d1 = reach[i] as number;
    const det = before.x * here.y - before.y * here.x;
    // Two faces that look the same way never cross. A footprint has no such
    // pair, but a shell measured to nothing could, so the corner falls back to
    // the face itself rather than to infinity.
    if (Math.abs(det) < 1e-9) out.push({ x: here.x * d1, y: here.y * d1 });
    else out.push({ x: (d0 * here.y - d1 * before.y) / det, y: (before.x * d1 - here.x * d0) / det });
  }
  return out;
}

/**
 * One wall of a band, wound to look outward. Drawing the hull back faces only
 * then leaves the far side of it standing outside the building that covers the
 * near side; a hull wound the other way would hide the building instead.
 */
function wall(
  positions: number[],
  normals: number[],
  ring: readonly Point[],
  faces: readonly Point[],
  y0: number,
  y1: number,
): void {
  for (let i = 0; i < ring.length; i++) {
    const a = ring[i] as Point;
    const b = ring[(i + 1) % ring.length] as Point;
    const face = faces[i] as Point;
    const n: [number, number, number] = [face.x, 0, face.y];
    push(positions, normals, [a.x, y0, a.y], [b.x, y1, b.y], [b.x, y0, b.y], n);
    push(positions, normals, [a.x, y0, a.y], [a.x, y1, a.y], [b.x, y1, b.y], n);
  }
}

/** One level triangle, wound to look up or down as asked. */
function flat(positions: number[], normals: number[], a: Point, b: Point, c: Point, y: number, up: boolean): void {
  const looksUp = (b.y - a.y) * (c.x - b.x) - (b.x - a.x) * (c.y - b.y) > 0;
  const n: [number, number, number] = up ? [0, 1, 0] : [0, -1, 0];
  if (looksUp === up) push(positions, normals, [a.x, y, a.y], [b.x, y, b.y], [c.x, y, c.y], n);
  else push(positions, normals, [a.x, y, a.y], [c.x, y, c.y], [b.x, y, b.y], n);
}

function push(
  positions: number[],
  normals: number[],
  a: readonly [number, number, number],
  b: readonly [number, number, number],
  c: readonly [number, number, number],
  n: readonly [number, number, number],
): void {
  positions.push(a[0], a[1], a[2], b[0], b[1], b[2], c[0], c[1], c[2]);
  for (let i = 0; i < 3; i++) normals.push(n[0], n[1], n[2]);
}

/**
 * The ground a building covers, as a ring in its own frame: `x` across the
 * frontage and `y` towards the road. It is the rectangle of the massing, with
 * the corner that faces a junction cut away exactly as the generator cuts it.
 */
function footprintRing(massing: BuildingMassing): Point[] {
  const hw = massing.width / 2;
  const hd = massing.depth / 2;
  const corners: Point[] = [
    { x: hw, y: hd },
    { x: -hw, y: hd },
    { x: -hw, y: -hd },
    { x: hw, y: -hd },
  ];
  const cut = massing.chamfer === 0 ? 0 : Math.min(CHAMFER_WIDTH, massing.width * 0.25, hw, hd);
  const out: Point[] = [];
  for (let i = 0; i < corners.length; i++) {
    const corner = corners[i] as Point;
    if (cut > 0 && Math.sign(corner.x) === massing.chamfer && corner.y > 0) {
      const prev = corners[(i + 3) % 4] as Point;
      const next = corners[(i + 1) % 4] as Point;
      out.push(towards(corner, prev, cut), towards(corner, next, cut));
    } else {
      out.push(corner);
    }
  }
  return out;
}

/** A point `distance` metres from `from` along the way to `to`. */
function towards(from: Point, to: Point, distance: number): Point {
  const span = Math.hypot(to.x - from.x, to.y - from.y) || 1;
  const t = Math.min(1, distance / span);
  return { x: from.x + (to.x - from.x) * t, y: from.y + (to.y - from.y) * t };
}

/**
 * A convex ring pushed out by the same distance all the way round. Each corner
 * moves along the bisector of the two edges that meet there, so every edge of
 * the ring ends up exactly `by` metres outside where it started.
 */
function expand(ring: readonly Point[], by: number): Point[] {
  const out: Point[] = [];
  for (let i = 0; i < ring.length; i++) {
    const before = outward(ring[(i + ring.length - 1) % ring.length] as Point, ring[i] as Point);
    const after = outward(ring[i] as Point, ring[(i + 1) % ring.length] as Point);
    const share = 1 + before.x * after.x + before.y * after.y;
    const p = ring[i] as Point;
    out.push({ x: p.x + (by * (before.x + after.x)) / share, y: p.y + (by * (before.y + after.y)) / share });
  }
  return out;
}

/**
 * The way an edge of a footprint faces. The ring is centred on the origin, so
 * the normal that points away from it is the one that points out of the ring.
 */
function outward(a: Point, b: Point): Point {
  const nx = b.y - a.y;
  const ny = -(b.x - a.x);
  const span = Math.hypot(nx, ny) || 1;
  const n = { x: nx / span, y: ny / span };
  const midX = (a.x + b.x) / 2;
  const midY = (a.y + b.y) / 2;
  return n.x * midX + n.y * midY < 0 ? { x: -n.x, y: -n.y } : n;
}

/**
 * Where a building stands, as the matrix from its own frame to the world.
 *
 * The frame is turned so `z` looks at the road the lot fronts, which is the way
 * `Building.facing` points. It stands on the lowest of the lot's four corners,
 * sunk by {@link FOUNDATION}: on a slope a wall is then buried at one end rather
 * than standing clear of the ground at the other.
 */
function matrixOf(building: Building, lookup: BuildingLookup, fit: number): Matrix4 {
  let ground = Infinity;
  for (const corner of building.lot) ground = Math.min(ground, lookup.heightAt(corner.x, corner.y));
  const middle = lotMiddle(building.lot);
  // A turn about the world's up axis takes the local frame's z to the heading
  // the lot faces; the quarter turn is the step from a heading on the map to an
  // angle about that axis.
  const turn = new Quaternion().setFromAxisAngle(new Vector3(0, 1, 0), Math.PI / 2 - building.facing);
  return new Matrix4().compose(new Vector3(middle.x, ground - FOUNDATION, middle.y), turn, new Vector3(fit, fit, fit));
}

/**
 * Which front corner of a lot is cut away, if either. The lot fronts one road
 * graph edge, so the junctions that can face it are the two ends of that edge; a
 * corner within reach of one takes the chamfer, and the nearer corner wins where
 * both are.
 */
function chamferOf(building: Building, graph: RoadGraph): number {
  const edge = graph.edges[building.road] as RoadEdge | undefined;
  if (edge === undefined) return 0;
  let best = CHAMFER_REACH;
  let side = 0;
  for (const node of [edge.from, edge.to]) {
    const at = graph.nodes[node];
    if (at === undefined || graph.degree(node) < JUNCTION_DEGREE) continue;
    // The first point of the lot is the corner that stands at local +x, the
    // second the one at -x: the frame runs along the frontage the other way.
    const corners = [building.lot[0] as Point, building.lot[1] as Point];
    for (let i = 0; i < corners.length; i++) {
      const corner = corners[i] as Point;
      const distance = Math.hypot(at.x - corner.x, at.y - corner.y);
      if (distance >= best) continue;
      best = distance;
      side = i === 0 ? 1 : -1;
    }
  }
  return side;
}

/** A number in 0..1 from a building's seed, for the draws the renderer makes. */
function unit(seed: number, salt: number): number {
  return hashInts(seed, salt) / 0x100000000;
}
